
import cloneDeep from 'lodash/cloneDeep';
import filter from 'lodash/filter';
import forEach from 'lodash/forEach';
import isNil from 'lodash/isNil';
import map from 'lodash/map';
import omit from 'lodash/omit';
import orderBy from 'lodash/orderBy';
import pick from 'lodash/pick';
import uniq from 'lodash/uniq';
import without from 'lodash/without';
import v4 from 'uuid/v4';
import Vue from 'vue';

import { getAPIDataFromRootNode } from '@src/helpers/formBuilder';
import IFormRenderable from '@srcmodules/form/interfaces/IFormRenderable';
import { move } from '../../helpers/array';
import { classes, components, data, renderables as renderableData } from './data';
import IBaseRenderable from './interfaces/IBaseRenderable';
import IClassDefinition, { IRelationData } from './interfaces/IClassDefinition';
import IClassRenderable from './interfaces/IClassRenderable';
import IFormData from './interfaces/IFormData';
import IMemberRenderable from './interfaces/IMemberRenderable';

interface IBaseComponent {
	type: string;
	tagName: string;
}

// A temporary definition to get us off the ground for now
interface IMemberDefinition {
	[property: string]: any;
}

interface IState {
	components: {[id: string]: IBaseComponent};
	renderables: {[id: string]: IClassRenderable|IMemberRenderable|IBaseRenderable};
	classes: {[id: string]: IClassDefinition};
	members: {[id: string]: IMemberDefinition};
	data: IFormData;
	selectedRenderable: string;
	selectedForm: string;
}

interface IUpdateRenderableParams {
	// The renderable id
	id: string|number;
	// The renderable property
	property: string;
	// The new value
	value: any;
}

// Our window global
declare global {
	interface Window { APP_FORM: any; }
}

export const initialState = {
	components,
	renderables: window.APP_FORM
		&& window.APP_FORM.definition
		&& window.APP_FORM.definition.renderables
			? window.APP_FORM.definition.renderables
			: {},
	classes: {},
	members: {},
	data,
	selectedRenderable: null,
	selectedForm: 'example-form'
} as IState;

/**
 * Make any necessary transformations to an incoming renderable before it's added to the state.
 */
function transformRenderableForState(renderable: IClassRenderable|IMemberRenderable|IBaseRenderable) {
	// A quick and dirty conditional, but we could use a lookup table
	// if more transformations were required.
	if (renderable.tagName === 'MemberElement') {
		const newRenderable = cloneDeep(renderable) as IMemberRenderable;
		newRenderable.definition = {};
	}
}

export const mutations = {
	/**
	 * Select a form to edit.
	 */
	selectForm(state: IState, formId: string) {
		state.selectedForm = formId;
	},

	/**
	 * Update the data in the store.
	 */
	updateData(state: IState, { model, id, property, value }: {
		// The model to update
		model: string,
		// The model id
		id: string|number
		// The property
		property: string
		// The property value
		value: any
	}) {
		if (!state.data[model]) {
			console.warn(`updateData() called, but no model for '${model}'`);
		}
		if (!state.data[model][id]) {
			console.warn(`updateData() called, but no id for '${model}' with id '${id}'`);
		}
		state.data[model][id][property] = value;
	},

	/**
	 * Create a renderable.
	 */
	createRenderable(state: IState, renderable: IClassRenderable|IMemberRenderable|IBaseRenderable) {
		transformRenderableForState(renderable);
		Vue.set(state.renderables, renderable.id, renderable);
	},

	/**
	 * Add renderables directly to the store.
	 */
	rehydrateRenderables(state: IState, renderables: {[id: string]: IClassRenderable|IMemberRenderable|IBaseRenderable}) {
		Vue.set(state, 'renderables', renderables);
	},

	/**
	 * Create classes from their definitions.
	 */
	createClasses(state: IState, classDefinitions: any[]) {
		classDefinitions.forEach((classDefinition) => {
			Vue.set(state.classes, classDefinition.class_type, classDefinition);
		});
	},

	/**
	 * Create members from their definitions.
	 */
	createMembers(state: IState, memberDefinitions: any[]) {
		memberDefinitions.forEach((memberDefinition) => {
			Vue.set(state.members, memberDefinition.id, memberDefinition);
		});
	},

	/**
	 * Update the classType of a renderable.
	 */
	updateClassType(state: IState, { id, classType, parentClassId, relationName }: {
		// The renderable id
		id: string
		// The new class name
		classType: string,
		// The parent class, if this class has a parent
		parentClassId?: string
		// The relation name, if this class represents a relation
		relationName?: string
	}) {
		if (!state.renderables[id]) {
			return console.warn(`updateClassType() called, but no renderable for id '${id}'`);
		}
		if (state.renderables[id].type !== 'ClassComponent') {
			return console.warn(`updateClassType() called, the element with id '${id}' is not a ClassComponent`);
		}
		if (!state.classes[classType]) {
			return console.warn(`updateClassType() called, but no class found for classType ${classType}`);
		}

		const classData = {...state.classes[classType]} as any;
		delete classData.relations;
		Vue.set((state.renderables as any), id, {
			...classData,
			...state.renderables[id],
			definition: {
				label: classData.definition.label,
				showLabel: false
			},
			parentClassId,
			relationName
		});
	},

	/**
	 * Add a data source to a class member.
	 *
	 */
	addDataSourceToClassMember(state: IState, { id, classMemberRef, dataSourceId, dataSourceMemberRef }: {
		// The id of the class renderable to update
		id: string,
		// The class member which will receive data
		classMemberRef: string,
		// The id of the data requirement
		dataSourceId: string,
		// The member of the data requirement
		dataSourceMemberRef: string
	}) {
		if (!state.renderables[id]) {
			return console.warn(`updateClassDeriveDataMap() called, but no renderable for id ${id}`);
		}
		// There are cases when json-encoded data spits back an empty array here, rather than an empty object.
		if (!(state.renderables[id] as IClassRenderable).dataSourceMap || Array.isArray((state.renderables[id] as IClassRenderable).dataSourceMap)) {
			Vue.set(state.renderables[id], 'dataSourceMap', {});
		}
		Vue.set((state.renderables[id] as IClassRenderable).dataSourceMap, classMemberRef, {
			id: dataSourceId,
			memberRef: dataSourceMemberRef
		});
	},

	/**
	 * Remove a data source from a class member.
	 */
	removeDataSourceFromClassMember(state: IState, { id, memberRef }: {
		// The id of the class renderable to update
		id: string,
		// The class member which will receive data
		memberRef: string
	}) {
		if (!state.renderables[id]) {
			return console.warn(`updateClassDeriveDataMap() called, but no renderable for id ${id}`);
		}
		if (!(state.renderables[id] as IClassRenderable).dataSourceMap) {
			return console.warn(`updateClassDeriveDataMap() called, but no derived data map for id ${id}`);
		}
		Vue.delete((state.renderables[id] as IClassRenderable).dataSourceMap, memberRef);
	},

	/**
	 * Update a renderable in the store.
	 */
	updateRenderable(state: IState, { id, property, value }: IUpdateRenderableParams) {
		if (!state.renderables[id]) {
			return console.warn(`updateRenderable() called, but no renderable for id '${id}'`);
		}
		Vue.set((state.renderables[id] as IBaseRenderable), property, value);
	},

	/**
	 * Update a renderable's definition in the store.
	 */
	updateRenderableDefinition(state: IState, { id, property, value }: IUpdateRenderableParams) {
		if (!state.renderables[id]) {
			return console.warn(`updateRenderable() called, but no renderable for id '${id}'`);
		}
		if (!(state.renderables[id] as IMemberRenderable).definition) {
			return console.warn(`updateRenderable() called, but no meta for renderable with id '${id}'`);
		}
		Vue.set((state.renderables[id] as IMemberRenderable).definition, property, value);
	},

	/**
	 * Update the renderable's item list in the store.
	 */
	updateRenderableItems(state: IState, { id, items }: {
		// The renderable id
		id: string|number
		// The new value
		items: string[]
	}) {
		if (!state.renderables[id]) {
			return console.warn(`updateRenderable() called, but no renderable for id '${id}'`);
		}

		const component = state.renderables[id] as IClassRenderable;
		Vue.set(state.renderables[id], 'items', items);
	},

	/**
	 * Select a given renderable.
	 */
	selectRenderable(state: IState, id: string) {
		state.selectedRenderable = id;
	},

	/**
	 * Add renderables to the given component. Renderables cannot be included twice in a form,
	 * so renderables already in the list will be discarded in favour of their earlier duplicates.
	 */
	addRenderablesToComponent(state: IState, { renderableIds, componentId }: { renderableIds: string[], componentId: string }) {
		const component = state.renderables[componentId] as IClassRenderable;
		if (!component) {
			return console.warn(`addRenderablesToComponent() called, but no component with id ${componentId}`);
		}
		const newItems = uniq(component.items.concat(renderableIds));
		component.items = newItems;
	},

	/**
	 * Remove a renderable from the state.
	 */
	removeRenderable(state: IState, id: string) {
		Vue.delete(state.renderables, id);
	},

	/**
	 * Remove renderables and their children from the given component, and remove them from the state.
	 */
	removeRenderablesFromComponent(state: IState, { renderableIds, componentId }: { renderableIds: string[], componentId: string }) {
		const component = state.renderables[componentId] as IClassRenderable;
		const newItems = without(component.items, ...renderableIds);
		component.items = newItems;

		// If one of these renderables is selected, remove the selection
		if (renderableIds.indexOf(state.selectedRenderable) !== -1) {
			state.selectedRenderable = null;
		}

		// If the renderable has any children, delete them recursively
		const removeRenderableAndChildren = (id: string) => {
			const renderable = state.renderables[id];
			if (renderable && (renderable as IClassRenderable).items) {
				(renderable as IClassRenderable).items.forEach(removeRenderableAndChildren);
			}

			// Delete the renderable
			Vue.delete(state.renderables, id);
		};

		renderableIds.forEach(removeRenderableAndChildren);
	},

	/**
	 * Move a renderable within its parent component
	 */
	moveRenderable(state: IState, { renderableId, componentId, index }: { renderableId: string, componentId: string, index: number }) {
		const component = state.renderables[componentId] as IClassRenderable;
		const renderableIndex = component.items.indexOf(renderableId);
		if (renderableIndex === -1) {
			return console.warn(`Could not find renderable ${renderableId} in component ${componentId}`);
		}
		if (index > (component.items.length - 1)) {
			return console.warn(`Index ${index} outside bounds of item array with length ${component.items.length}`);
		}
		move(component.items, renderableIndex, index);
	}
};

export const getters = {
	/**
	 * Get a class by its ID.
	 */
	getClass: (state: IState) => (classId: string) => {
		return state.classes[classId];
	},

	/**
	 * Get all classes.
	 */
	getClasses: (state: IState) => () => {
		return state.classes;
	},

	/**
	 * Get a member by its ID.
	 */
	getMember: (state: IState) => (memberId: string): IMemberDefinition => {
		return state.members[memberId];
	},

	/**
	 * Get all members.
	 */
	getMembers: (state: IState) => () => {
		return state.members;
	},

	/**
	 * Get the data requirements for the form.
	 */
	getDataSources: (state: IState, localGetters: any) => () => {
		return localGetters.getRenderable(localGetters.getSelectedForm()).dataSources;
	},

	/**
	 * Get the list of members that can be used as data sources.
	 *
	 * These are derived from the form's dataSources, which list a set of
	 * class instances that will be available to the form when it's rendered
	 * for the user.
	 */
	getMembersFromDataSources: (state: IState, localGetters: any) => () => {
		const membersByDataSourceLabel = {} as {[id: string]: {
			id: string,
			label: string,
			members: string[]
		}};
		forEach(localGetters.getDataSources(), (dataSource: any) => {
			membersByDataSourceLabel[dataSource.id] = {
				id: dataSource.id,
				label: dataSource.label,
				members: filter<IMemberDefinition>(localGetters.getMembers(), (member) => {
					return member.class_type === dataSource.class_type;
				}).map((member: IMemberDefinition) => member.member_ref)
			};
		});
		return membersByDataSourceLabel;
	},

	/**
	 * Get a renderable by its ID.
	 */
	getRenderable: (state: IState) => (renderableId: string): IBaseRenderable => {
		return state.renderables[renderableId];
	},

	/**
	 * Get all the renderables.
	 */
	getRenderables: (state: IState) => () => {
		return state.renderables;
	},

	/**
	 * Get the ID of the selected form.
	 */
	getSelectedForm: (state: IState) => () => {
		return state.selectedForm;
	},

	/**
	 * Get the ID of the selected form.
	 */
	getSelectedRenderable: (state: IState) => () => {
		return state.selectedRenderable;
	},

	/**
	 * Does the given renderable belong to the given component?
	 */
	isRenderableInComponent: (state: IState) => ({ renderableId, componentId }: { renderableId: string, componentId: string }) => {
		const component = state.renderables[componentId] as IClassRenderable;
		if (!component) {
			return console.warn(`isRenderableInComponent() called, but no component with id ${componentId}`);
		}
		if (component.items.indexOf(renderableId) !== -1) {
			return true;
		}
		return false;
	},

	/**
	 * Does the given member already exist in the given component?
	 */
	isMemberInComponent: (state: IState, localGetters: any) => ({ memberId, parentId }: { memberId: string, parentId: string }) => {
		const parentRenderable = state.renderables[parentId] as IClassRenderable;
		if (!parentRenderable) {
			return console.warn(`isMemberInComponent() called, but no component with id ${parentId}`);
		}
		const memberName = localGetters.getMember(memberId).definition.name;
		const memberIds = parentRenderable.items.map((renderableId) => {
			const renderable = localGetters.getRenderable(renderableId);
			return renderable.tagName === 'MemberElement'
				? renderable.definition.name
				: null;
		});
		if (memberIds.indexOf(memberName) !== -1) {
			return true;
		}
		return false;
	},

	/**
	 * Get the parent for the given element.
	 */
	getParentOfRenderable: (state: IState, localGetters: any) => (renderableId: string): IBaseRenderable|void => {
		let parentId = null;
		forEach(state.renderables, (renderable: IClassRenderable) => {
			if (renderable.items && renderable.items.indexOf(renderableId) !== -1) {
				parentId = renderable.id;
			}
		});
		if (!parentId) {
			return null;
		}
		return state.renderables[parentId];
	},

	/**
	 * Is this renderable, or any of its parents, a repeater?
	 */
	doesRenderableOrItsParentsRepeat: (state: IState, localGetters: any) => {
		const doesRenderableParentRepeat = (renderableId: string): boolean => {
			const parent = localGetters.getParentOfRenderable(renderableId);
			// If there's no parent, we're at the form root
			if (!parent) {
				return false;
			}
			// If the parent matches the form root, it doesn't repeat
			if (parent.id === localGetters.getSelectedForm) {
				return false;
			}
			// Otherwise, depend on the parent definition
			if (parent.definition && parent.definition.isRepeater) {
				return true;
			}
			return doesRenderableParentRepeat(parent.id);
		};
		return (renderableId: string): boolean => {
			const renderable = localGetters.getRenderable(renderableId);
			if (!renderable) {
				console.warn('doesRenderableOrItsParentsRepeat called, but no renderable for', renderableId);
				return false;
			}
			if (renderable.definition && renderable.definition.isRepeater) {
				return true;
			}
			return doesRenderableParentRepeat(renderableId);
		};
	}
};

const getMemberId = (member_ref: string, classRef: string) => `${classRef}::${member_ref}`;

const actions = {
	/**
	 * Add a data requirement to the selected form.
	 */
	addDataSource(context: any, { class_type, label }: { class_type: string, label: string }) {
		const renderable = context.getters.getRenderable(context.getters.getSelectedForm());
		const id = v4();
		const value = {
			...renderable.dataSources,
			[id]: {
				class_type,
				label,
				id
			}
		};
		context.commit('updateRenderable', {
			id: renderable.id,
			property: 'dataSources',
			value
		});
		return id;
	},

	/**
	 * Modify a data source label.
	 */
	updateDataSourceLabel(context: any, { id, label }: { id: number, label: string }) {
		const renderable = context.getters.getRenderable(context.getters.getSelectedForm());
		const dataSources = {...renderable.dataSources};
		dataSources[id] = {
			class_type: renderable.dataSources[id].class_type,
			label,
			id
		};
		context.commit('updateRenderable', {
			id: renderable.id,
			property: 'dataSources',
			value: dataSources
		});
	},

	/**
	 * Remove a data requirement from the selected form.
	 */
	removeDataSource(context: any, id: string) {
		const renderable: IFormRenderable = context.getters.getRenderable(context.getters.getSelectedForm());

		// Commit the new dataSources array without the specified dataSource
		context.commit('updateRenderable', {
			id: renderable.id,
			property: 'dataSources',
			value: omit(renderable.dataSources, id)
		});
	},

	/**
	 * Fetch the classes from the page, and persist them and their members to the store.
	 */
	fetchClasses(context: any, localClasses: IClassDefinition[]) {
		const members: IMemberRenderable[] = [];
		// We've got to do a little translation here, parsing JSON, namespacing member variables to
		// ensure that they don't conflict with eachother when stored in a normalised map, and
		// removing redundant data. We also extract relations via link_multi.
		localClasses = cloneDeep<IClassDefinition[]>(localClasses).map((classObject: any) => {
			const relations: IRelationData[] = [];
			const classMembers = map(classObject.members, (member: any) => {
				// Add the necessary data
				const memberId = getMemberId(member.member_ref, classObject.class_type);
				member.id = memberId;
				member.class_type = classObject.class_type;
				member.tagName = 'MemberElement';
				try {
					member.definition = JSON.parse(member.definition);
				} catch (e) {
					console.warn(`There was an error parsing the member definition for member ${member.member_ref}
						in class ${classObject.class_type}. It's possible that the data definitions passed to the form builder
						are malformed. This member's definition will be blank as a result.`);
					member.definition = {};
				}

				// Add this member as a relation, if it's a link.
				// We leave these members as members, too, as they could represent
				// either a repeater field or a (single|multi)select.
				if (member.data_type_ref === 'link_multi' || member.data_type_ref === 'link_uni') {
					if (member.definition.dataMapKey) {
						relations.push({
							classId: member.link_class,
							name: member.member_ref
						});
					} else {
						console.warn('Odd result - member has a data_type_ref but no dataMapKey');
					}
				}

				// Remove the data we don't need - we only care about properties that
				// let us derive member behaviour
				delete member.map_field;
				delete member.label;
				delete member.description;
				delete member.choices;
				const order = member.definition.order;
				member.definition = pick(member.definition, [
					'class',
					'hint',
					'label',
					'name',
					'placeholder',
					'required'
				]);

				members.push(member);
				return {
					memberId,
					order
				};
			})
			// Get rid of empty values
			.filter((member) => !!member)
			// Sort by the definition order
			.sort((a: {memberId: string, order: number}, b: {memberId: string, order: number}) => {
				if (a.order < b.order) {
					return -1;
				}
				if (a.order === b.order) {
					return 0;
				}
				return 1;
			})
			// Transform to an id
			.map((memberData: {memberId: string, order: number}) => memberData.memberId);

			return {
				// We use a subset of the class data here.
				...pick(classObject, ['label', 'class_type', 'module']),
				id: classObject.class_type,
				definition: JSON.parse(classObject.definition),
				members: classMembers,
				relations
			};
		});

		context.commit('createClasses', localClasses);
		context.commit('createMembers', members);
	},

	/**
	 * Save the form, posting the data to a Neon Phoebe endpoint.
	 */
	save(context: any, id: string) {
		const renderables = cloneDeep(context.getters.getRenderables());
		const rootNode = renderables[id];
		if (!id) {
			console.warn(`Attempted to save, but there is no data at ${id}`);
			return;
		}
		if (!rootNode.form_ref) {
			console.warn(`Attempted to save, but there is no form_ref for renderable with id ${id}`);
			return;
		}
		const body = JSON.stringify({
			...getAPIDataFromRootNode(rootNode),
			renderables
		});
		fetch((window as any).neon.url('/phoebe/appforms/api/form/save', { class: rootNode.form_ref }), {
			method: 'POST',
			body,
			headers: {
				'Content-Type' : 'application/json',
				'X-CSRF-Token' : (window as any).neon.csrfToken()
			},
			credentials: 'include'
		}).then((response) => {
			response.json().then(console.log);
		}).catch((error) => {
			console.warn('Error saving form data', error);
		});
	}
};

const formModule = {
	strict: true,
	state: initialState,
	mutations,
	getters,
	actions
};

export default formModule;



