










import Vue from 'vue';

import BaseRenderableMixin from './BaseRenderableMixin';

export default Vue.extend({
	name: 'HeadingElement',
	mixins: [BaseRenderableMixin],
	props: {
		options: {
			type: Object,
			required: true
		},
		composable: Boolean
	},
	computed: {
		containerClasses(): { HeadingElement: boolean, 'HeadingElement--composable': boolean, 'HeadingElement--is-selected': boolean } {
			return {
				'HeadingElement': true,
				'HeadingElement--composable': this.composable,
				'HeadingElement--is-selected': this.isSelected
			};
		},

	}
});




