























import Vue from 'vue';
import BaseRenderableMixin from './BaseRenderableMixin';

export default Vue.extend({
	name: 'ClassComponent',
	mixins: [BaseRenderableMixin],
	props: {
		id: [String, Number],
		options: {
			type: Object,
			required: true
		},
		composable: Boolean,
		isLast: Boolean,
		index: Number
	},
	computed: {
		containerClasses(): { ClassComponent: boolean, 'ClassComponent--composable': boolean, 'ClassComponent--repeatable': boolean, 'ClassComponent--selected': boolean } {
			return {
				'ClassComponent': true,
				'ClassComponent--composable': this.composable,
				'ClassComponent--repeatable': this.options.definition.isRepeater,
				'ClassComponent--selected': (this as any).isSelected
			};
		},
		canRepeat(): boolean {
			return !this.composable && this.isLast && this.options.definition && this.options.definition.isRepeater;
		}
	}
});




