import Vue from 'vue';

/**
 * Create getters and setters for the given property of the renderable definition property.
 * The substitute property, if supplied, will be added from the *root* of the renderable data.
 * It can be used to, for example, substitute an ID if a name doesn't exist.
 */
export const createDefinitionGetterSetter = (propertyName: string, substituteProperty?: string) => ({
	get(): any {
		if (!substituteProperty) {
			return this.data.definition[propertyName];
		}
		return this.data.definition[propertyName] !== undefined ? this.data.definition[propertyName] : this.data[substituteProperty];
	},
	set(value: any) {
		this.$store.commit('updateRenderableDefinition', {
			id: this.data.id,
			property: propertyName,
			value
		});
	}
});

const baseRenderableMixin = Vue.extend({
	name: 'BaseRenderableMixin',
	computed: {
		/**
		 * Getters and settings for the 'name' value.
		 */
		name: createDefinitionGetterSetter('name', 'id')
	}
});

export default baseRenderableMixin;



