








import marked from 'marked';
import Vue from 'vue';

import BaseRenderableMixin from './BaseRenderableMixin';

export default Vue.extend({
	name: 'GuidanceElement',
	mixins: [BaseRenderableMixin],
	props: {
		options: {
			type: Object,
			required: true
		},
		composable: Boolean
	},
	computed: {
		containerClasses(): { GuidanceElement: boolean, 'GuidanceElement--composable': boolean, 'GuidanceElement--selected': boolean } {
			return {
				'GuidanceElement': true,
				'GuidanceElement--composable': this.composable,
				'GuidanceElement--selected': this.isSelected
			};
		}
	},
	methods: {
		marked(input: string) {
			return marked(input);
		}
	}
});




