




















import filter from 'lodash/filter';
import without from 'lodash/without';
import Vue from 'vue';
import draggable from 'vuedraggable';

const componentIconMap = {
	GuidanceElement: 'font',
	DescriptionElement: 'font',
	HeadingElement: 'font',
	SpacerElement: 'minus',
	ClassComponent: 'file',
} as {[componentName: string]: string};

/**
 * @component ComponentMenu
 *
 * A ComponentMenu presents the components available in the form components store
 * as a list of draggable items. These items can then be dragged onto a composable
 * form, to be edited and arranged as usual.
 */
export default Vue.extend({
	name: 'ComponentMenu',
	components: {
		draggable
	},
	computed: {
		/**
		 * The available components.
		 */
		components: {
			get() {
				// We don't want member elements. We could do this in a more
				// data oriented way if there were lots of non-visible components
				// here.
				return without(Object.keys(this.$store.state.form.components), 'memberElement');
			}
		},
	},
	methods: {
		/**
		 * Get a single component by id.
		 */
		getComponent(id: string) {
			return this.$store.state.form.components[id];
		},

		/**
		 * Get the icon slug for a component.
		 */
		getComponentIcon(tag: string) {
			return componentIconMap[tag] || '';
		}
	}
});




