



























import v4 from 'uuid/v4';
import Vue from 'vue';

import ComponentMenuView from './components/ComponentMenuView.vue';
import PhoebeForm from './components/PhoebeForm.vue';
import PhoebeFormMetaEditor from './components/PhoebeFormMetaEditor.vue';
import RenderableDetailView from './components/RenderableDetailView.vue';

export default Vue.extend({
	name: 'app',
	components: {
		PhoebeForm,
		RenderableDetailView,
		ComponentMenuView,
		PhoebeFormMetaEditor
	},

	/**
	 * @inheritdoc
	 *
	 * We pull the form from the window definition here, or, if no definition
	 * exists, create a new form to save.
	 */
	beforeCreate() {
		this.$store.dispatch('fetchClasses', window.APP_FORM.classes);
		if (window.APP_FORM && window.APP_FORM.definition && window.APP_FORM.definition.renderables) {
			this.$store.commit('rehydrateRenderables', window.APP_FORM.definition.renderables);
			this.$store.commit('selectForm', window.APP_FORM.definition.rootNode);
		} else {
			// This id is a placeholder for the user to edit.
			const id = v4();
			const name = 'New form';
			this.$store.commit('createRenderable', {
				id,
				name,
				gridItems: [],
				items: [],
				dataSources: {},
				type: 'FormComponent'
			});
			this.$store.commit('selectForm', id);
		}
	},
	computed: {
		renderableData() {
			return this.$store.getters.getRenderables();
		},
		selectedForm() {
			return this.$store.getters.getSelectedForm();
		}
	}
});




