import find from 'lodash/find';
import isUndefined from 'lodash/isUndefined';

import IBaseRenderable from '@src/modules/form/interfaces/IBaseRenderable';
import IFormRenderable from '@src/modules/form/interfaces/IFormRenderable';
import IClassRenderable from '../modules/form/interfaces/IClassRenderable';
import IMemberRenderable from '../modules/form/interfaces/IMemberRenderable';

export function getTypeFromClass(className: string) {
	let type = className.split('\\').pop();
	// long component name =
	type = className.replace(/\\/g, '-');
	// look up map
	return type.toLowerCase();
}

export function makeUniqueName(name: string, count: number) {
	count = count || 1;
	name = name || 'field';
	if (isNameUnique(name)) {
		return name;
	} else {
		// If it is not unique append an '_#' number recursively incrementing # until it is unique
		const regex = /_[0-9]+$/g;
		name = name.match(regex) ?  name.replace(regex, '_' + count) : name += '_' + count;
		count ++;
		return this.makeUniqueName(name, count);
	}
}

/**
 * @return boolean true if the name is unique within the field collection
 */
export function isNameUnique(name: string) {
	// var result = isUndefined(find(FormBuilderApp.Store.state.form.fields, {name: name}));
	// return result;
	return true;
}

/**
 * Get the data relevant to the Neon API from the renderable that
 * acts as the form root.
 */
export function getAPIDataFromRootNode(renderable: IFormRenderable) {
	return {
		rootNode: renderable.id,
		gridItems: renderable.gridItems,
		dataSources: renderable.dataSources,
		name: renderable.name,
		form_ref: renderable.form_ref
	};
}

/**
 * Get the editable properties for the given form field class.
 */
export function getFieldProperties(fieldClass: string) {
	// Right now, we're returning the same thing for everything.
	// This might change as the list of editable things changes -
	// see the map below for an example.
	return [
		'form-builder-field-form-element-name',
		'form-builder-field-form-element-label',
		'form-builder-field-form-element-hint',
		'form-builder-field-form-element-required',
		'form-builder-field-form-element-readonly'
	];
}

type TFieldClasses = 'neon\\core\\form\\fields\\Text'
	| 'neon\\core\\form\\fields\\Checkbox'
