








import Vue from 'vue';

import ClassComponentDetail from './renderables/ClassComponentDetail.vue';
import DescriptionElementDetail from './renderables/DescriptionElementDetail.vue';
import MemberElementDetail from './renderables/MemberElementDetail.vue';
import SpacerElementDetail from './renderables/SpacerElementDetail.vue';

export default Vue.extend({
	name: 'RenderableDetailView',
	components: {
		ClassComponentDetail,
		MemberElementDetail,
		DescriptionElementDetail,
		GuidanceElementDetail: DescriptionElementDetail,
		HeadingElementDetail: DescriptionElementDetail,
		SpacerElementDetail
	},
	computed: {
		/**
		 * Get the form cursor.
		 */
		selectedRenderable(): string {
			return this.$store.getters.getSelectedRenderable();
		},

		/**
		 * Get the renderable from the id in the props.
		 */
		renderable(): string|void {
			return this.$store.getters.getRenderable(this.selectedRenderable) || null;
		},
	}
});




