/**
 * Move an element in a given array from one index to another. Done in-place with splice().
 * Cribbed from https://github.com/brownieboy/array.prototype.move/blob/master/src/array-prototype-move.js
 * @param {Array} array
 * @param {number} oldIndex
 * @param {number} newIndex
 * @return {Array} The amended array
 */
export function move(array: any[], oldIndex: number, newIndex: number) {
	while (oldIndex < 0) {
		oldIndex += array.length;
	}
	while (newIndex < 0) {
		newIndex += array.length;
	}
	if (newIndex >= array.length) {
		let k = newIndex - array.length;
		while ((k--) + 1) {
			array.push(undefined);
		}
	}
	array.splice(newIndex, 0, array.splice(oldIndex, 1)[0]);
	return array;
}



