Vue.component('form-builder-field-form-dynamic-map', Vue.extend({
	props: {
		field: Object,
	},
	template: `
			<div>
				<div class='form-group' >
					<label class='control-label' for='placeholder'>Data Map Key</label>
					<select v-model='field.dataMapKey' class='form-control'>
						<option v-for='(type, key) in mapTypes' :value='key'>
							{{ type }}
						</option>
					</select>
				</div>
			</div>
		`,
	computed: {
		mapTypes() {
			return this.$store.state.dds.map_types;
		},
	},
	methods: {
		updateProvider(e: any) {
			this.field.dataMapProvider = e.target.value;
			this.$store.commit('updateField', {field: this.field});
		},
		updateKey(e: any) {
			this.field.dataMapKey = e.target.value;
			this.$store.commit('updateField', {field: this.field});
		},
	},
}));

