Vue.component('form-builder-field-form-element-list-items',  Vue.extend({
	props: {
		field: Object,
	},
	components: {
		draggable,
	},
	template: `
		<div class='form-group'>
			<label class='control-label' for='form-text'>Options <button @click='addOption()' class='btn btn-default' style='border-radius:100px'>+</button></label>
			<draggable v-model='choicesList' :options='dragOptions'>
				<div class='input-group' v-for='(item, index) in choicesList' style='padding:5px 0'>
					<div class='dragGrip' style='display: table-cell'></div>
					<input style='width:50%' placeholder='Key, e.g GB' :value='item.key' @input='updateOptionKey($event, item)' type='text' name='options' class='form-control' >
					<input style='width:50%' placeholder='Description, e.g Great Britain' :value='item.value' @input='updateOptionValue($event, item)' type='text' name='options' class='form-control' >
					<span style='padding:8px 8px' :disabled='field.items.length == 1' @click='removeOption(item, index)' data-remove-btn='' class='btn btn-default input-group-addon' >-</span>
					<span style='padding:8px 8pxborder-radius: 0 3px 3px 0' @click='addOption(item, index)' data-add-btn='' class='btn btn-default input-group-addon '>+</span>
				</div>
			</draggable>
		</div>
	`,
	computed: {
		dragOptions() {
			return  {
				animation: 100,
				// group: 'description',
				// disabled: !this.editable,
				ghostClass: 'ghost',
			};
		},
		choicesList: {
			get() {
				return this.field.items;
			},
			set(list: any) {
				this.field.items = list;
				this.$store.commit('updateField', {field: this.field});
			},
		},
	},
	methods: {
		addOption(item: any, index: any) {
			const newNumber = (this.field.items.length + 1);
			const newItem = { key: 'Key ' + newNumber, value: 'Option ' + newNumber };
			if (isUndefined(item) && isUndefined(index)) {
				this.field.items.unshift(newItem);
			} else {
				this.field.items.splice(index + 1, 0, newItem);
			}
			this.$store.commit('updateField', {field: this.field});
		},
		removeOption(item: any, index: any) {
			if (this.field.items.length > 1) {
				this.field.items.splice(index, 1);
				this.$store.commit('updateField', {field: this.field});
			}
		},
		updateOptionKey(event: any, item: any) {
			item = find(this.field.items, {key: item.key});
			item.key = event.target.value;
			this.$store.commit('updateField', {field: this.field});
		},
		updateOptionValue(event: any, item: any) {
			item = find(this.field.items, {key: item.key});
			item.value = event.target.value;
			this.$store.commit('updateField', {field: this.field});
		},
	},
}));

