Vue.component('neon-switch-input', Vue.extend({
	props: {
		name: {type: String},
		size: {
			type: String,
			default: '',
		},
		value: Boolean,
		onLabel: {
			type: String,
			default: 'On',
		},
		offLabel: {
			type: String,
			default: 'Off',
		},
	},
	template: `
		<label :class=''switch switch--' + size'>
			<input :name='name' type='hidden' value='0' />
			<input :name='name' type='checkbox' value='1' @change='update' :checked='value' >
			<div class='switch__slider switch__slider--round'>
				<div class='switch__on'>{{ onLabel }}</div>
				<div class='switch__off'>{{ offLabel }}</div>
			</div>
		</label>
	`,
	methods: {
		update() {
			this.$emit('input', !this.value);
		},
	},
}));



