











import Vue from 'vue'

import BaseRenderableMixin from './BaseRenderableMixin'

export default Vue.extend({
  name: 'MemberElement',
  mixins: [BaseRenderableMixin],
  props: {
    options: {
      type: Object,
      required: true
    },
    modelId: [Number, String],
    model: Object,
    composable: Boolean
  },
  computed: {
    containerClasses(): { MemberElement: boolean, 'MemberElement--composable': boolean, 'MemberElement--is-selected': boolean } {
      return {
        MemberElement: true,
        'MemberElement--composable': this.composable,
        'MemberElement--is-selected': this.isSelected
      }
    },
    memberValue: {
      get(): any {
        return this.model[this.options.member]
      },
      set(value: any) {
        this.$store.commit('updateData', {
          model: this.options.class_type,
          id: this.modelId,
          property: this.options.member,
          value
        })
      }
    }
  }
});




