








import marked from 'marked';
import Vue from 'vue';

export default Vue.extend({
	name: 'DescriptionElement',
	props: {
		options: {
			type: Object,
			required: true
		},
		composable: Boolean
	},
	computed: {
		containerClasses(): { DescriptionElement: boolean, 'DescriptionElement--composable': boolean } {
			return {
				'DescriptionElement': true,
				'DescriptionElement--composable': this.composable
			};
		}
	},
	methods: {
		marked(input: string) {
			return marked(input);
		}
	}
});




