import Vue from 'vue';

import { getFieldProperties } from '@src/helpers/formBuilder';
import BaseRenderableMixin, { createDefinitionGetterSetter } from './BaseRenderableMixin';

export default Vue.extend({
	name: 'MemberElementDetail',
	mixins: [BaseRenderableMixin],
	props: {
		data: Object
	},
	computed: {
		description: createDefinitionGetterSetter('description'),

		/**
		 * Should this member's data be visible in the Neon form instance grid?
		 */
		displayInGrid: {
			get() {
				const selectedFormId = this.$store.getters.getSelectedForm();
				return this.$store.getters.getRenderable(selectedFormId).gridItems.indexOf(this.data.id) !== -1;
			},
			set(value: boolean) {
				const selectedFormId = this.$store.getters.getSelectedForm();
				if (!this.displayInGrid) {
					this.$store.commit('updateRenderable', {
						id: selectedFormId,
						property: 'gridItems',
						value: [this.data.id, ...this.$store.getters.getRenderable(selectedFormId).gridItems]
					});
				} else {
					this.$store.commit('updateRenderable', {
						id: selectedFormId,
						property: 'gridItems',
						value: without(this.$store.getters.getRenderable(selectedFormId).gridItems, this.data.id)
					});
				}
			}
		},

		fieldProperties() {
			return getFieldProperties(this.data.definition.class);
		},

		/**
		 * Can this member's data be visible in the Neon form instance grid?
		 *
		 * If the member has repeatable parents, this isn't possible.
		 */
		canShowInGrid() {
			return this.$store.getters.doesRenderableOrItsParentsRepeat(this.data.id);
		}
	}
});




