










import Vue from 'vue';

export default Vue.extend({
	name: 'TextHighlighter',
	props: {
		originalString: String,
		searchString: String
	},
	computed: {
		stringData(): { leadingString: string, highlightString: string, trailingString: string } {
			let leadingString;
			let highlightString;
			let trailingString;

			// If we have a search string ...
			if (this.searchString && this.originalString) {
				const startNum = this.originalString.toLowerCase().indexOf(this.searchString.toLowerCase());
				// ... and a match ...
				if (startNum !== -1) {
					// ... construct the leading, highlighted, and trailing parts of the string.
					const endNum = startNum + this.searchString.length;
					leadingString = this.originalString.substring(0, startNum);
					highlightString = this.originalString.substring(startNum, endNum);
					trailingString = this.originalString.substring(endNum, this.originalString.length);
				}
			}

			return {
				leadingString,
				highlightString,
				trailingString
			};
		}
	}
});




